SELECT i.id, i.code, i.title, i.type, i.priority, i.status, i.description, i.project_id, i.device_id, i.reporter_id, i.assignee_id, i.cc_users, i.due_date, i.resolved_at, i.closed_at, i.closed_reason, i.create_time, i.update_time, p.name AS project_name, d.name AS device_name, r.name AS reporter_name, a.name AS assignee_name FROM t_issue i LEFT JOIN t_project p ON i.project_id = p.id AND p.deleted = 0 LEFT JOIN t_device d ON i.device_id = d.id AND d.deleted = 0 LEFT JOIN t_user r ON i.reporter_id = r.id AND r.deleted = 0 LEFT JOIN t_user a ON i.assignee_id = a.id AND a.deleted = 0 WHERE i.deleted = 0
AND (i.code LIKE CONCAT('%', #{query.keyword}, '%') OR i.title LIKE CONCAT('%', #{query.keyword}, '%'))
AND i.project_id = #{query.projectId}
AND i.device_id = #{query.deviceId}
AND i.type = #{query.type}
AND i.priority = #{query.priority}
AND i.status = #{query.status}
AND i.reporter_id = #{query.reporterId}
AND i.assignee_id = #{query.assigneeId}
AND i.create_time >= #{query.startDate}
AND i.create_time <= #{query.endDate}
ORDER BY CASE WHEN #{query.sortOrder} = 'asc' THEN CASE #{query.sortField} WHEN 'priority' THEN CASE i.priority WHEN 'urgent' THEN 1 WHEN 'high' THEN 2 WHEN 'medium' THEN 3 ELSE 4 END WHEN 'create_time' THEN i.create_time ELSE i.create_time END END ASC, CASE WHEN #{query.sortOrder} = 'desc' OR #{query.sortOrder} IS NULL OR #{query.sortOrder} = '' THEN CASE #{query.sortField} WHEN 'priority' THEN CASE i.priority WHEN 'urgent' THEN 1 WHEN 'high' THEN 2 WHEN 'medium' THEN 3 ELSE 4 END WHEN 'create_time' THEN i.create_time ELSE i.create_time END END DESC

SELECT COUNT(*)
FROM t_issue i
WHERE i.deleted = 0

